//! Renders the codemap.md text (same layout as the old codemap.sh).

use std::collections::BTreeMap;

use crate::model::{FileEntry, Index};
use crate::query;

/// Folders shown in the "by folder" summary line.
const TOP_FOLDERS: usize = 8;

pub fn render(project: &str, index: &Index) -> String {
    let mut out = format!(
        "# Code map of {project} (auto-generated by codegraph; do not edit)\n\
         Search: rg '<name>' .claude/codemap.md (hits are path:line) · callers: codegraph callers <name>\n\
         Files: {} · by folder: {}\n",
        index.files.len(),
        folder_summary(index)
    );
    // Plain pushes, not `write!`: tokio has ~20k lines and formatting each one cost half of `update`.
    out.reserve(index.files.values().map(approx_len).sum());
    for entry in index.files.values() {
        push_section(&mut out, index, entry);
    }
    out
}

/// The text of one file: `\n## path (N lines)`, its `uses:` line, then one line per symbol.
fn push_section(out: &mut String, index: &Index, entry: &FileEntry) {
    out.push_str("\n## ");
    out.push_str(&entry.path);
    out.push_str(" (");
    push_number(out, entry.lines);
    out.push_str(" lines)\n");
    let imports = query::local_imports(index, entry);
    if !imports.is_empty() {
        out.push_str("uses: ");
        out.push_str(&imports.join(", "));
        out.push('\n');
    }
    for s in &entry.symbols {
        out.push_str(&entry.path);
        out.push(':');
        push_number(out, s.line);
        out.push(' ');
        out.push_str(&s.signature);
        out.push('\n');
    }
}

/// The paths a codemap has sections for, in order.
pub fn section_paths(text: &str) -> Vec<&str> {
    text.match_indices("\n## ")
        .filter_map(|(at, _)| header_path(text, at))
        .collect()
}

/// `text` with the section of `entry` replaced by a fresh one, everything else untouched. `index`
/// only has to know the project's file paths and aliases (for the `uses:` line). `None` when the
/// codemap has no such section (a new file: that needs a full render).
pub fn splice(text: &str, index: &Index, entry: &FileEntry) -> Option<String> {
    let (start, end) = find_section(text, &entry.path)?;
    let mut fresh = String::new();
    push_section(&mut fresh, index, entry);
    Some([&text[..start], &fresh, &text[end..]].concat())
}

/// Byte range of the section of `path`: from its leading newline to the next section (or the end).
/// The whole header line is compared, so `a` never matches the section of `a (b).rs`.
fn find_section(text: &str, path: &str) -> Option<(usize, usize)> {
    let mut starts = text.match_indices("\n## ").map(|(at, _)| at);
    let start = starts.find(|&at| header_path(text, at) == Some(path))?;
    let end = starts.next().unwrap_or(text.len());
    Some((start, end))
}

/// The path in the header line that starts at `at` (`\n## path (N lines)`).
fn header_path(text: &str, at: usize) -> Option<&str> {
    let line = text[at + 4..].lines().next()?;
    line.strip_suffix(" lines)")?
        .rsplit_once(" (")
        .map(|(path, _)| path)
}

/// A close guess of the text one file adds, to size the buffer once.
fn approx_len(entry: &crate::model::FileEntry) -> usize {
    let symbols: usize = entry
        .symbols
        .iter()
        .map(|s| entry.path.len() + s.signature.len() + 8)
        .sum();
    entry.path.len() + 24 + symbols
}

/// Append `n` in decimal without going through the formatting machinery.
fn push_number(out: &mut String, mut n: u32) {
    let mut digits = [0u8; 10];
    let mut at = digits.len();
    loop {
        at -= 1;
        digits[at] = b'0' + (n % 10) as u8;
        n /= 10;
        if n == 0 {
            break;
        }
    }
    // Only ASCII digits were written, so this never fails.
    if let Ok(text) = std::str::from_utf8(&digits[at..]) {
        out.push_str(text);
    }
}

/// `src(12) tests(3)`: the biggest folders first.
fn folder_summary(index: &Index) -> String {
    let mut counts: BTreeMap<&str, usize> = BTreeMap::new();
    for path in index.files.keys() {
        let dir = path.rsplit_once('/').map_or(".", |(d, _)| d);
        *counts.entry(dir).or_default() += 1;
    }
    let mut folders: Vec<_> = counts.into_iter().collect();
    folders.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(b.0)));
    folders
        .iter()
        .take(TOP_FOLDERS)
        .map(|(d, n)| format!("{d}({n})"))
        .collect::<Vec<_>>()
        .join(" ")
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::model::{FileEntry, Kind, Symbol};

    fn entry(path: &str, lines: u32, signatures: &[&str]) -> FileEntry {
        use crate::model::{Kind, Symbol};
        FileEntry {
            path: path.into(),
            lines,
            symbols: signatures
                .iter()
                .enumerate()
                .map(|(i, sig)| Symbol {
                    name: format!("f{i}"),
                    kind: Kind::Fn,
                    line: i as u32 + 1,
                    signature: (*sig).into(),
                    container: None,
                    returns: None,
                })
                .collect(),
            ..FileEntry::default()
        }
    }

    #[test]
    fn splicing_an_edited_file_equals_a_full_render() {
        let mut index = Index::default();
        for e in [
            entry("a.rs", 3, &["fn a()"]),
            entry("b.rs", 5, &["fn b()", "fn c()"]),
            entry("c.rs", 1, &[]),
        ] {
            index.files.insert(e.path.clone(), e);
        }
        let before = render("p", &index);
        assert_eq!(section_paths(&before), vec!["a.rs", "b.rs", "c.rs"]);
        for edited in ["a.rs", "b.rs", "c.rs"] {
            let mut after = index.clone();
            let new = entry(edited, 9, &["fn renamed()", "fn more()"]);
            after.files.insert(edited.into(), new.clone());
            assert_eq!(
                splice(&before, &after, &new).unwrap(),
                render("p", &after),
                "editing {edited}"
            );
        }
        assert_eq!(splice(&before, &index, &entry("new.rs", 1, &[])), None);
    }

    #[test]
    fn a_path_that_is_a_prefix_of_another_never_matches_its_section() {
        let mut index = Index::default();
        for e in [
            entry("a", 1, &["fn x()"]),
            entry("a (b).rs", 2, &["fn y()"]),
        ] {
            index.files.insert(e.path.clone(), e);
        }
        let before = render("p", &index);
        assert_eq!(section_paths(&before), vec!["a", "a (b).rs"]);
        for edited in ["a", "a (b).rs"] {
            let mut after = index.clone();
            let new = entry(edited, 7, &["fn z()"]);
            after.files.insert(edited.into(), new.clone());
            assert_eq!(splice(&before, &after, &new).unwrap(), render("p", &after));
        }
    }

    #[test]
    fn numbers_are_written_like_display_does() {
        for n in [0, 7, 10, 99, 100, 65_535, 1_000_000, u32::MAX] {
            let mut out = String::new();
            push_number(&mut out, n);
            assert_eq!(out, n.to_string());
        }
    }

    #[test]
    fn renders_like_codemap_sh() {
        let mut index = Index::default();
        index.files.insert(
            "src/lib.rs".into(),
            FileEntry {
                path: "src/lib.rs".into(),
                lines: 60,
                imports: vec!["game_core".into(), "tiles".into()],
                symbols: vec![Symbol {
                    name: "parse".into(),
                    kind: Kind::Fn,
                    line: 11,
                    signature: "pub fn parse(input: &str) -> Option<Temp>".into(),
                    container: None,
                    returns: None,
                }],
                ..FileEntry::default()
            },
        );
        index.files.insert(
            "main.rs".into(),
            FileEntry {
                path: "main.rs".into(),
                lines: 3,
                ..FileEntry::default()
            },
        );
        let want = "\
# Code map of demo (auto-generated by codegraph; do not edit)
Search: rg '<name>' .claude/codemap.md (hits are path:line) · callers: codegraph callers <name>
Files: 2 · by folder: .(1) src(1)

## main.rs (3 lines)

## src/lib.rs (60 lines)
uses: game_core, tiles
src/lib.rs:11 pub fn parse(input: &str) -> Option<Temp>
";
        assert_eq!(render("demo", &index), want);
    }

    #[test]
    fn uses_line_lists_only_local_imports_for_typescript() {
        let mut index = Index::default();
        index.files.insert(
            "a.ts".into(),
            FileEntry {
                path: "a.ts".into(),
                imports: vec!["./x".into(), "react".into()],
                ..FileEntry::default()
            },
        );
        assert!(render("demo", &index).contains("uses: ./x\n"));
    }
}
